def tr(text):
    if not isinstance(text,str): return text
    reverse={target:source for source,target in EN.items()}
    text=reverse.get(text,text)
    if LANGUAGE != 'en': return text
    if text in EN: return EN[text]
    for source,target in sorted(EN.items(),key=lambda item:len(item[0]),reverse=True):
        if len(source)>5: text=text.replace(source,target)
    return text
